// WAHA inbound -> lead. So mensagem que CHEGA e que cita uma peca.
//
// REGRA DURA - o Config esta com includeOtherFields=true, entao o body do
// webhook chega aqui dentro do $input junto com os tokens. Nao chamar
// $('Webhook...') pelo nome: ao importar por cima de um canvas existente o n8n
// renomeia os nos (Config -> Config1) e a referencia morre em silencio.
//
// NAO usar barra invertida em regex: some ao colar o codigo na mao no n8n.
const inp = $input.first().json;
const body = inp.body || {};
const p = body.payload || {};

// 1) Nunca reagir ao proprio envio.
if (p.fromMe) return [];

const from = String(p.from || '');
if (!from) return [];

// 2) Ignorar GRUPO. O hook dispara pra tudo - inclusive a oferta que o bot
//    acabou de postar. Sem este freio, cada disparo viraria um lead fantasma.
if (from.indexOf('@g.us') > -1) return [];

// 3) Precisa citar uma peca. O CTA manda "Estou interessado! (m71370664392)".
const texto = String(p.body || '');
const m = texto.match(/m[0-9]+/i);
if (!m) return [];   // "oi" solto nao vira lead; o Bruno le no WhatsApp normal

const d = p._data || {};
return [{ json: {
  mercari_id: m[0].toLowerCase(),
  phone: from.split('@')[0],
  nome_wa: String(p.notifyName || d.notifyName || p.pushName || '').trim(),
  mensagem: texto,
  recebido_em: new Date().toISOString()
}}];

// Junta as duas consultas e monta a linha do lead.
//  - $input          = os leads QUE JA EXISTEM desta peca (dedup + ordinal)
//  - achar a peca    = a linha da 556 (row_id pro link + title_pt pro aviso)
const lead = $('Filtrar + montar lead').first().json;
const leadRows = ($input.first().json.results) || [];
const pecaRows = ($('Baserow: achar a peca').first().json.results) || [];

// Mesma pessoa + mesma peca = nao duplica linha NEM aviso. (2 mensagens do
// mesmo cliente nao podem virar 2 pings no zap do Bruno.)
const eu = String(lead.phone).trim();
for (const r of leadRows) {
  if (String(r.phone || '').trim() === eu) return [];
}

const peca = pecaRows.length ? pecaRows[0] : null;
const titulo = (peca && peca.title_pt) ? peca.title_pt : lead.mercari_id;

// A linha vai montada daqui: o HTTP node so faz JSON.stringify($json.row).
// Campo `peca` = link_row -> quer um ARRAY de row_id, nao o mercari_id.
// Peca nao encontrada (link solto): grava o lead assim mesmo, com peca vazia.
// Perder o lead por causa do link seria pior que um link faltando.
const row = {
  lead: lead.nome_wa || lead.phone,
  phone: lead.phone,
  nome_wa: lead.nome_wa,
  mercari_id: lead.mercari_id,
  peca: peca ? [peca.id] : [],
  mensagem: lead.mensagem,
  recebido_em: lead.recebido_em,
  status: 'Novo',
  avisado_vendido: false
};

return [{ json: {
  row: row,
  ordinal: leadRows.length + 1,
  peca_titulo: titulo,
  phone: lead.phone,
  nome_wa: lead.nome_wa
}}];

// Monta o aviso pro Bruno. O lead JA foi gravado - se este no falhar, o dado
// esta salvo e so o ping se perde.
const cfg = $('Config').first().json;
const d = $('Dedup + ordinal').first().json;

const quem = d.nome_wa || d.phone;
const nth = d.ordinal > 1 ? ' (' + d.ordinal + 'a pessoa)' : '';
const texto = '🔔 Lead: ' + quem + '\n' + d.peca_titulo + nth + '\nwa.me/' + d.phone;

// Sem admin_id nao ha pra quem avisar. O lead continua gravado.
const destino = String(cfg.admin_id || '').trim();
if (!destino) return [];

return [{ json: { payload: {
  session: cfg.waha_session,
  chatId: destino,
  text: texto
}}}];
